package io.github.limuyang2.router.info

import io.github.limuyang2.router.IRouterInstance

/**
 * 路由页面的完整静态解析信息。
 *
 * 由 KSP 处理器根据 `@Router` 声明生成，包含 URL 结构、页面描述、关联的页面拦截器以及实例工厂。
 *
 * Complete static routing metadata for a destination.
 *
 * Generated by the KSP processor from `@Router` declarations; contains the URL structure, description,
 * associated page interceptors, and the instance factory.
 *
 * @param url 完整路由 URL 映射（不含查询参数） / Complete route URL mapping (without query parameters).
 * @param scheme 路由协议 / Route scheme.
 * @param host 路由主机名 / Route host.
 * @param path 路由路径 / Route path.
 * @param desc 页面描述文本 / Page description text.
 * @param pushInterceptors 绑定的页面级 Push 拦截器列表 / List of bound page-level push interceptors.
 * @param popInterceptors 绑定的页面级 Pop 拦截器列表 / List of bound page-level pop interceptors.
 * @param instanceProvider 实例工厂，用于通过参数创建该路由类的实例 / Instance provider creating instances with parameters.
 */
data class ParseRouterInfo(
    val url: String,
    val scheme: String,
    val host: String,
    val path: String,
    val desc: String,
    val pushInterceptors: List<ParsePagePushInterceptorInfo>,
    val popInterceptors: List<ParsePagePopInterceptorInfo>,
    val instanceProvider: IRouterInstance
)
